commands.command:
cat > /etc/nginx/sites-available/backend8090 <<'ANTRIEB_NGINX_SITE'
server {
    listen 8090 default_server;
    listen [::]:8090 default_server;
    server_name _;

    access_log /var/log/nginx/backend8090.access.log;
    error_log /var/log/nginx/backend8090.error.log;

    location / {
        proxy_pass http://127.0.0.1:8091;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
ANTRIEB_NGINX_SITE
ln -sfn /etc/nginx/sites-available/backend8090 /etc/nginx/sites-enabled/backend8090
nginx -t
